    // log(cosh(x))
    // For large |x|, cosh(x) ~ 0.5 * exp(|x|), so log(cosh(x)) ~ |x| - log(2)
    // Using the identity: log(cosh(x)) = x - log(1 + exp(-2x)) for x > 0
    // and log(cosh(x)) = -x - log(1 + exp(2x)) for x < 0
    if (x >= 0.0) {
        return x - log1p(exp(-2.0 * x));
    } else {
        return -x - log1p(exp(2.0 * x));
