    double dx = x_curr - x_prev;

    // Threshold for "nearly equal" inputs
    // Choose based on expected precision and signal range. 
    // 1e-9 is a typical machine epsilon scale, but audio signals might require larger.
    const double epsilon = 1e-9; 

    if (fabs(dx) < epsilon) {
        // Case for nearly equal inputs: return the function value at the sample point
        return tanh(x_prev);
    } else {
        // General case: difference quotient of the antiderivative
        double F_curr = F_tanh(x_curr);
        double F_prev = F_tanh(x_prev);
        return (F_curr - F_prev) / dx;
    }
}
```

